import{I as r,o as l,c as h,b6 as i,J as u,w as o,j as n,a as s}from"./chunks/framework.BUXTSoD9.js";const g=JSON.parse('{"title":"Mit Jobs to Be Done herausfinden, was Nutzer wirklich erreichen wollen","description":"Ein Einf&uuml;hrungsartikel zu Jobs to Be Done f&uuml;r Einsteiger. Verstehen Sie, dass Nutzer keine Funktionen kaufen, sondern in bestimmten Szenarien Ihr Produkt \\"einstellen\\", um einen Fortschritt zu erzielen. Lernen Sie, mit JTBD Produktrichtungen, Interviewfragen und AI-Prompts zu strukturieren.","frontmatter":{"title":"Mit Jobs to Be Done herausfinden, was Nutzer wirklich erreichen wollen","description":"Ein Einf&uuml;hrungsartikel zu Jobs to Be Done f&uuml;r Einsteiger. Verstehen Sie, dass Nutzer keine Funktionen kaufen, sondern in bestimmten Szenarien Ihr Produkt \\"einstellen\\", um einen Fortschritt zu erzielen. Lernen Sie, mit JTBD Produktrichtungen, Interviewfragen und AI-Prompts zu strukturieren."},"headers":[],"relativePath":"de-de/stage-1/appendix-jobs-to-be-done/index.md","filePath":"de-de/stage-1/appendix-jobs-to-be-done/index.md"}'),d={name:"de-de/stage-1/appendix-jobs-to-be-done/index.md"},b=Object.assign(d,{setup(c){const a="Etwa <strong>1,5 Stunden</strong>";return(p,e)=>{const t=r("ChapterIntroduction");return l(),h("div",null,[e[1]||(e[1]=i('<h1 id="mit-jobs-to-be-done-herausfinden-was-nutzer-wirklich-erreichen-wollen" tabindex="-1">Mit Jobs to Be Done herausfinden, was Nutzer wirklich erreichen wollen <a class="header-anchor" href="#mit-jobs-to-be-done-herausfinden-was-nutzer-wirklich-erreichen-wollen" aria-label="Permalink to “Mit Jobs to Be Done herausfinden, was Nutzer wirklich erreichen wollen”">​</a></h1><p><a id="top-jtbd"></a></p><h2 id="kapitel-uuml-bersicht" tabindex="-1">Kapitelübersicht <a class="header-anchor" href="#kapitel-uuml-bersicht" aria-label="Permalink to “Kapitel&amp;uuml;bersicht”">​</a></h2>',3)),u(t,{duration:a,tags:["JTBD","Nutzerbedürfnisse","Produktdenken","Bedarfserkenntnis"],coreOutput:"1 JTBD-Satz, der einem echten Bedarf näher kommt",expectedOutput:"Eine vage Idee zu einem konkreteren Nutzerszenario und einer MVP-Richtung verdichten können"},{default:o(()=>[...e[0]||(e[0]=[n("p",null,'Viele Anfänger machen bei der Produktentwicklung am häufigsten den Fehler, ihre gesamte Aufmerksamkeit auf "Welche Funktionen will ich bauen" zu richten. Man sieht, dass andere intelligente Kategorisierung haben, man will auch welche; man sieht, dass andere automatische Zusammenfassung haben, man will auch welche; man sieht, dass andere Agenten, Multimodalität und Workflows gebaut haben, man fühlt sich auch nicht zurückbleiben.',-1),n("p",null,'In der Realität entscheiden sich Nutzer aber selten deshalb für ein Produkt, weil "der Funktionsname cool klingt". Vielmehr möchten sie in einem bestimmten Moment etwas voranbringen und "stellen" ad hoc ein Werkzeug, einen Service oder sogar eine Person ein, die ihnen bei diesem Schritt hilft.',-1),n("p",null,[s("Genau das ist es, was die "),n("strong",null,"Jobs to Be Done (JTBD)"),s(" -Methode uns verdeutlichen will: "),n("strong",null,"Nutzer kaufen nicht die Funktion an sich, sondern stellen eine Lösung ein, die ihnen hilft, einen Fortschritt zu erzielen.")],-1),n("p",null,"Dieser Artikel führt Sie in verständlicher Sprache durch JTBD und macht es zu einem Analysewerkzeug, das Sie direkt bei der Entwicklung von AI-Anwendungen einsetzen können.",-1)])]),_:1}),e[2]||(e[2]=i(`<div class="info custom-block"><p class="custom-block-title">Minimales SOP</p><p><strong>Ziel</strong>: Nach dem Lesen wissen Sie besser, wie Sie eine vage Idee in einen Satz mit echtem Nutzerszenario verdichten, anstatt nur eine Sammlung von Funktionsnamen im Kopf zu haben.</p><p><strong>Aktionspunkte</strong>: 1 vage Idee aufschreiben, 3 potenzielle Nutzer nach &quot;Wie haben Sie das letzte Mal damit umgebracht&quot; fragen und dann zu 1 JTBD-Satz zusammenfassen.</p><p><strong>Ergebnis</strong>: Sie erhalten eine klarere Bedarfshypothese und wissen, was in der ersten Version prioritär gelöst werden sollte.</p><p><strong>Stichwortsprünge</strong>: <a href="#jtbd-what">Was ist JTBD</a> · <a href="#jtbd-formula">Ein-Satz-Formel</a> · <a href="#jtbd-ai">Wie AI Ihnen hilft</a></p></div><h2 id="was-sie-lernen-werden" tabindex="-1">Was Sie lernen werden <a class="header-anchor" href="#was-sie-lernen-werden" aria-label="Permalink to “Was Sie lernen werden”">​</a></h2><ol><li>Was Jobs to Be Done ist und warum es näher an echten Bedürfnissen liegt als &quot;Funktions-Brainstorming&quot;</li><li>Wie man unterscheidet zwischen &quot;Funktionen, die Nutzer sagen zu wollen&quot; und &quot;was Nutzer wirklich erreichen wollen&quot;</li><li>Wie man mit einer einfachen Vorlage eine vage Idee in Szenario, Auslöser, Hindernis und Erfolgskriterium zerlegt</li><li>Wie man JTBD bei AI-Produkten, Interview-Fragen und Prompt-Strukturierung anwendet</li></ol><p><a id="jtbd-what"></a></p><h2 id="_1-was-ist-jobs-to-be-done" tabindex="-1"><a href="#top-jtbd">1. Was ist Jobs to Be Done?</a> <a class="header-anchor" href="#_1-was-ist-jobs-to-be-done" aria-label="Permalink to “1. Was ist Jobs to Be Done?”">​</a></h2><p>Jobs to Be Done wird oft als <strong>JTBD</strong> abgekürzt. Die Kernidee dahinter hängt mit dem klassischen Ausdruck zusammen, den Clayton Christensens Team verbreitet hat: <strong>Nutzer &quot;stellen&quot; ein Produkt ein, um etwas zu erledigen.</strong></p><p>Dieses &quot;Etwas&quot; ist keine oberflächliche Aktion auf einer To-do-Liste, sondern ein <strong>Fortschritt</strong>, den der Nutzer für seinen Zustand anstrebt. Zum Beispiel:</p><ul><li>Nicht &quot;Ich brauche ein AI-Protokoll-Tool&quot;, sondern &quot;Ich möchte innerhalb von 10 Minuten nach einem Meeting die wichtigsten Punkte, Aufgaben und Verantwortlichen zusammenfassen, anstatt mich auf Erinnerung zu verlassen&quot;</li><li>Nicht &quot;Ich brauche eine Haushaltsbuch-App&quot;, sondern &quot;Ich möchte wissen, wohin mein Geld geht, damit ich am Monatsende nicht mehr ängstlich bin&quot;</li><li>Nicht &quot;Ich brauche einen Lebenslauf-Optimierer&quot;, sondern &quot;Ich möchte zuversichtlicher einen ansehnlichen Lebenslauf verschicken, ohne bei jeder Bewerbung zu zweifeln, dass er schlecht geschrieben ist&quot;</li></ul><p>Deshalb konzentriert sich <strong>JTBD nicht darauf, wie das Produkt aussieht, sondern darauf, warum der Nutzer es in diesem Moment braucht.</strong></p><p>Das erklärt auch, warum viele scheinbar unterschiedliche Produkte tatsächlich um denselben Job konkurrieren. Wenn ein Nutzer &quot;auf dem Arbeitsweg weniger gelangweilt sein&quot; möchte, könnte er Kurzvideos, Podcasts, Spiele, Chats oder sogar Nickerchen einsetzen. Wenn ein Nutzer &quot;ein langes PDF schnell verstehen&quot; möchte, könnte er AI-Zusammenfassungs-Tools, Praktikanten, Kollegen, sich selbst durchbeißen oder es erst einmal liegen lassen.</p><p>Mit dieser Perspektive werden Sie feststellen, dass Ihre wahren Konkurrenten oft nicht nur &quot;eine andere App, die wie Ihre aussieht&quot; sind, sondern <strong>alle akzeptablen Alternativlösungen, die dem Nutzer aktuell zur Verfügung stehen.</strong></p><h2 id="_2-worin-unterscheidet-sich-jtbd-von-personas-und-funktionslisten" tabindex="-1">2. Worin unterscheidet sich JTBD von Personas und Funktionslisten? <a class="header-anchor" href="#_2-worin-unterscheidet-sich-jtbd-von-personas-und-funktionslisten" aria-label="Permalink to “2. Worin unterscheidet sich JTBD von Personas und Funktionslisten?”">​</a></h2><p>Viele Einsteiger beginnen die Bedarfsanalyse mit Personas: 25 Jahre alt, weiblich, Großstadt, Büroangestellte, mag Effizienz-Tools, offen für neue Produkte. Diese Informationen sind nicht ganz nutzlos, aber sie <strong>erklären oft nicht, warum eine Person in diesem Moment handelt.</strong></p><p>JTBD interessiert sich eher für folgende Fragen:</p><ul><li>In welchem Szenario hat er beschlossen, nach einer Lösung zu suchen?</li><li>Was genau hat ihn blockiert?</li><li>Was möchte er zum nächsten Schritt voranbringen?</li><li>Mit welchem behelfsmäßigen Ansatz hält er sich aktuell über Wasser?</li><li>Welches Ergebnis würde ihn das Gefühl haben lassen: &quot;Es hat sich gelohnt&quot;</li></ul><p>Mit anderen Worten: <strong>Personas beschreiben eher, wer dieser Mensch ungefähr ist; JTBD beschreibt eher, was dieser Mensch jetzt wirklich erreichen will.</strong></p><p>Gleichzeitig führen Funktionslisten oft in die Irre. Nutzer sagen: &quot;Ich will Word-Export&quot;, &quot;Ich will AI-Umschreibung&quot;, &quot;Ich will Spracheingabe&quot;. Das sind alles oberflächliche Äußerungen. JTBD fragt weiter:</p><ul><li>Warum benötigen Sie jetzt Word-Export und nicht PDF?</li><li>Möchten Sie umschreiben, weil der Stil schlecht ist, oder weil Sie verschiedene Zielgruppen ansprechen müssen?</li><li>Möchten Sie Spracheingabe, weil Sie nicht tippen möchten, oder weil Sie häufig unterwegs, beim Autofahren oder direkt nach Meetings aufzeichnen?</li></ul><p>Oft ist <strong>eine Funktion nur eine vorläufige Übersetzung eines Jobs.</strong> Wenn Sie nur Funktionen sammeln, machen Sie leicht ein Produkt, das &quot;alles aufstapelt, was Nutzer sagen&quot;. Wenn Sie den dahinterliegenden Job erkennen, haben Sie eher die Chance, eine wirklich handliche und wettbewerbsfähige Lösung zu entwickeln.</p><h2 id="_3-ein-beispiel-das-auch-einsteiger-verstehen" tabindex="-1">3. Ein Beispiel, das auch Einsteiger verstehen <a class="header-anchor" href="#_3-ein-beispiel-das-auch-einsteiger-verstehen" aria-label="Permalink to “3. Ein Beispiel, das auch Einsteiger verstehen”">​</a></h2><p>Lassen Sie uns zunächst nicht an komplexe AI-Produkte denken, sondern mit einem Alltagsbeispiel beginnen.</p><p>Angenommen, jemand hat morgens vor dem Verlassen des Hauses keine Zeit zum Frühstück und kauft oft ein Sandwich und Kaffee am U-Bahn-Eingang. Oberflächlich betrachtet &quot;kauft&quot; er ein Frühstück. Mit der JTBD-Perspektive könnte das, was er wirklich erreichen will, jedoch sein:</p><ul><li>An einem morgendlichen Tag in Eile mit minimalem geistigen Aufwand eine Mahlzeit organisieren</li><li>Sicherstellen, dass er vor der Ankunft im Büro nicht hungrig wird</li><li>Sein Arbeitsweg-Tempo nicht durch Frühstück beeinträchtigen</li></ul><p>In diesem Fall stellt der Nutzer nicht &quot;eine bestimmte Sandwich-Marke&quot; ein, sondern eine Lösung, die ihm hilft, seinen Morgen reibungslos zu gestalten. Wenn der nahe gelegene Supermarkt schneller, näher und zuverlässiger ist, könnte er sofort wechseln.</p><p>Diesen Logik auf AI-Produkte übertragen, wird es noch offensichtlicher.</p><p>Wenn Sie beispielsweise ein &quot;AI-Meeting-Protokoll-Tool&quot; entwickeln möchten, würden Sie auf Funktionsebene leicht darüber nachdenken:</p><ul><li>Audio-Upload unterstützen</li><li>Sprecher-Trennung integrieren</li><li>Markdown-Export anbieten</li><li>Automatische Aufgaben generieren</li></ul><p>Das alles ist nicht falsch, aber noch nicht ausreichend. Mit JTBD eine Ebene tiefer gefragt, könnte der Nutzer Folgendes wirklich erreichen wollen:</p><ul><li>Innerhalb von 10 Minuten nach dem Meeting die Diskussionsergebnisse an nicht anwesende Personen weiterleiten</li><li>Aufgaben, Verantwortliche und Fristen sauber extrahieren, damit das Team nicht aus dem Gedächtnis zusammenarbeiten muss</li><li>Die Zeit für wiederholtes Zusammenfassen von Meeting-Inhalten reduzieren und Energie für Entscheidungen und Fortschritt aufwenden</li></ul><p>Sobald der Job klar formuliert ist, ergeben sich viele Funktionsprioritäten automatisch. Vielleicht ist das Wichtigste in der ersten Version nicht &quot;12 Exportformate unterstützen&quot;, sondern:</p><ul><li>Protokollstruktur muss klar genug sein</li><li>Aufgabenerkennung muss zuverlässig sein</li><li>Freigabelink muss bequem sein</li><li>Ergebnisse müssen direkt an das Team weitergeleitet werden können</li></ul><p>Das ist der Wert von JTBD: <strong>Es hilft Ihnen, von &quot;Welche Fähigkeiten will ich aufstapeln&quot; zurückzukehren zu &quot;Welchen Fortschritt will ich dem Nutzer ermöglichen&quot;.</strong></p><h2 id="_4-eine-n-uuml-tzliche-jtbd-vorlage" tabindex="-1">4. Eine nützliche JTBD-Vorlage <a class="header-anchor" href="#_4-eine-n-uuml-tzliche-jtbd-vorlage" aria-label="Permalink to “4. Eine n&amp;uuml;tzliche JTBD-Vorlage”">​</a></h2><p>Wenn Sie Einsteiger sind, müssen Sie JTBD zunächst nicht zu akademisch betrachten. Konzentrieren Sie sich auf die 5 wichtigsten Elemente.</p><h3 id="_4-1-szenario" tabindex="-1">4.1 Szenario <a class="header-anchor" href="#_4-1-szenario" aria-label="Permalink to “4.1 Szenario”">​</a></h3><p>In welchem Moment und in welcher Umgebung denkt der Nutzer an dieses Produkt?</p><ul><li>Nach einem Meeting</li><li>Wenn der Chef spontan Material anfordert</li><li>Abends bei der Vorbereitung einer Bewerbung</li><li>Am Monatsende, wenn das Geld wieder nicht reicht</li></ul><p><strong>Ein Bedarf ohne Szenario ist meist noch nicht echt genug.</strong></p><h3 id="_4-2-ausl-ouml-ser" tabindex="-1">4.2 Auslöser <a class="header-anchor" href="#_4-2-ausl-ouml-ser" aria-label="Permalink to “4.2 Ausl&amp;ouml;ser”">​</a></h3><p>Was bringt ihn dazu, sofort nach einer Lüsung zu suchen?</p><ul><li>Von langen Dokumenten überwältigt und weiß nicht, wo man anfangen soll</li><li>Morgen muss Material abgegeben werden, heute erst gemerkt, dass das Format chaotisch ist</li><li>Gerade vom Chef nach dem Fortschritt gefragt und bemerkt, dass man nicht klar zusammengefasst hat</li><li>Möchte kontinuierlich aufzeichnen, aber handschriftlich, kopieren und zusammenstellen ist zu aufwendig</li></ul><p>Auslöser sind oft emotional aufgeladen. Diese Emotion ist wichtig, denn sie bestimmt, warum der Nutzer in diesem Moment handelt.</p><h3 id="_4-3-gew-uuml-nschter-fortschritt" tabindex="-1">4.3 Gewünschter Fortschritt <a class="header-anchor" href="#_4-3-gew-uuml-nschter-fortschritt" aria-label="Permalink to “4.3 Gew&amp;uuml;nschter Fortschritt”">​</a></h3><p>Er will nicht nur &quot;eine Aktion ausführen&quot;, sondern sich in einen neuen Zustand bringen:</p><ul><li>Von Chaos zu Klarheit</li><li>Von Angst zu Sicherheit</li><li>Von Aufschieben zu Aufbrechen</li><li>Von Ineffizienz zu Leichtigkeit</li><li>Von Unklarheit zu direkter Lieferung</li></ul><p>In diesem Schritt ist das Wort &quot;Fortschritt&quot; entscheidend. Denn viele kaufen nicht das Werkzeug, sondern die <strong>Zustandsveränderung.</strong></p><h3 id="_4-4-aktuelle-alternativl-ouml-sung" tabindex="-1">4.4 Aktuelle Alternativlösung <a class="header-anchor" href="#_4-4-aktuelle-alternativl-ouml-sung" aria-label="Permalink to “4.4 Aktuelle Alternativl&amp;ouml;sung”">​</a></h3><p>Wie macht er es ohne Ihr Produkt?</p><ul><li>Manuell kopieren und einfügen</li><li>Mit Excel oder Notizen kämpfen</li><li>Kollegen um Hilfe bitten</li><li>Aufschieben</li><li>Zwischen mehreren Tools hin- und herwechseln</li></ul><p>Wer die Alternative ist, das ist Ihre echte Wettbewerbsumgebung.</p><h3 id="_4-5-erfolgskriterium" tabindex="-1">4.5 Erfolgskriterium <a class="header-anchor" href="#_4-5-erfolgskriterium" aria-label="Permalink to “4.5 Erfolgskriterium”">​</a></h3><p>Wann gilt das Problem als wirklich gelöst?</p><ul><li>Innerhalb von 10 Minuten ein teilbares Ergebnis erhalten</li><li>Ohne größere Nachbearbeitung an andere versenden können</li><li>Keine wichtigen Punkte übersehen, keine Fehler machen, nichts vergessen</li><li>Beim ersten Mal wissen, wie es weitergeht</li></ul><p>Wenn Sie nicht einmal sagen können, &quot;wie der Nutzer beurteilt, ob es sich gelohnt hat&quot;, ist die Richtung wahrscheinlich noch nicht ausreichend konvergiert.</p><p><a id="jtbd-formula"></a></p><h2 id="_5-eine-direkt-anwendbare-ein-satz-formel" tabindex="-1"><a href="#top-jtbd">5. Eine direkt anwendbare Ein-Satz-Formel</a> <a class="header-anchor" href="#_5-eine-direkt-anwendbare-ein-satz-formel" aria-label="Permalink to “5. Eine direkt anwendbare Ein-Satz-Formel”">​</a></h2><p>Wenn Sie eine Produktrichtung strukturieren möchten, können Sie zunächst diese sehr praktische Formel verwenden:</p><blockquote><p>Wenn __________, möchte ich __________, um __________. Aktuell kann ich __________ nur mühsam nutzen, um dieses Ziel zu erreichen.</p></blockquote><p>Beispiel:</p><blockquote><p>Wenn ich nach einem informationsreichen Projektmeeting fertig bin, möchte ich schnell ein Protokoll mit Aufgaben, Verantwortlichen und Fristen erhalten, um sofort mein Team zu informieren und die Umsetzung voranzutreiben. Aktuell kann ich nur durch eigene Erinnerung, Durchsuchen von Chat-Verläufen und manuelle Zusammenstellung mühsam dieses Ziel erreichen.</p></blockquote><p>Ein weiteres Beispiel:</p><blockquote><p>Wenn ich mich auf eine neue Stelle bewerbe, möchte ich schnell meine bisherigen Erfahrungen in eine Version umschreiben, die besser zur Stelle passt, um zuversichtlicher einen ansehnlichen Lebenslauf verschicken zu können. Aktuell kann ich nur durch wiederholtes Kopieren des alten Lebenslaufs und manuelles Ändern der Formulierungen mühsam dieses Ziel erreichen, und am Ende bin ich immer unsicherer.</p></blockquote><p>Wenn Sie einen Satz auf diese Klarheitsstufe bringen können, wird das darauf folgende Seitendesign, die Prompt-Gestaltung und die Priorisierung von Funktionen deutlich einfacher.</p><h2 id="_6-bei-ai-produkten-drei-job-ebenen-besonders-beachten" tabindex="-1">6. Bei AI-Produkten: Drei Job-Ebenen besonders beachten <a class="header-anchor" href="#_6-bei-ai-produkten-drei-job-ebenen-besonders-beachten" aria-label="Permalink to “6. Bei AI-Produkten: Drei Job-Ebenen besonders beachten”">​</a></h2><p>Viele AI-Produkte wirken in Funktionsdemonstrationen beeindruckend, können Nutzer nach dem echten Launch jedoch nicht halten. Der häufige Grund: Nur die oberflächliche Aktion wurde gelöst, nicht der tiefere Job.</p><p>Sie können einen Job grob in drei Ebenen unterteilen:</p><h3 id="_6-1-funktionsebene" tabindex="-1">6.1 Funktionsebene <a class="header-anchor" href="#_6-1-funktionsebene" aria-label="Permalink to “6.1 Funktionsebene”">​</a></h3><p>Was ist die oberflächlichste Aufgabe?</p><ul><li>Dokumente zusammenfassen</li><li>Texte umschreiben</li><li>Aufgaben extrahieren</li><li>Bilder generieren</li></ul><p>Das ist die Ebene, die Nutzer am leichtesten aussprechen.</p><h3 id="_6-2-emotionale-ebene" tabindex="-1">6.2 Emotionale Ebene <a class="header-anchor" href="#_6-2-emotionale-ebene" aria-label="Permalink to “6.2 Emotionale Ebene”">​</a></h3><p>Welche Unannehmlichkeit möchte der Nutzer reduzieren oder welches Gefühl gewinnen?</p><ul><li>Nicht so in Panik sein wollen</li><li>Nicht unprofessionell wirken wollen</li><li>Nicht jedes Mal bei null anfangen wollen</li><li>Mehr Kontrolle haben wollen</li></ul><p>Viel Zahlungsbereitschaft hängt tatsächlich stark mit der emotionalen Ebene zusammen.</p><h3 id="_6-3-soziale-ebene" tabindex="-1">6.3 Soziale Ebene <a class="header-anchor" href="#_6-3-soziale-ebene" aria-label="Permalink to “6.3 Soziale Ebene”">​</a></h3><p>Wie möchte der Nutzer in den Augen anderer erscheinen?</p><ul><li>Zuverlässiger wirken</li><li>Im Team besser organisiert erscheinen</li><li>Vor Kunden professioneller auftreten</li><li>Auf Social-Media-Plattformen besser ausdrücken können</li></ul><p>Wenn Sie nur die Funktionsebene bedienen, ist das Produkt leicht ersetzbar; wenn Sie gleichzeitig die emotionale und soziale Ebene verstehen, finden Sie eher einen wirklich klebrigen Wert.</p><h2 id="_7-jtbd-umgekehrt-zur-produktrichtungsfilterung-nutzen" tabindex="-1">7. JTBD umgekehrt zur Produktrichtungsfilterung nutzen <a class="header-anchor" href="#_7-jtbd-umgekehrt-zur-produktrichtungsfilterung-nutzen" aria-label="Permalink to “7. JTBD umgekehrt zur Produktrichtungsfilterung nutzen”">​</a></h2><p>Manchmal haben Sie noch kein Produkt, sondern 3 bis 5 Ideen und wissen nicht, welche Sie umsetzen sollen. JTBD eignet sich hervorragend als Filter.</p><p>Nehmen Sie jede Idee und stellen Sie sich 5 Fragen:</p><ol><li>Ist das Szenario, das dieser Idee entspricht, konkret genug?</li><li>Nutzt der Nutzer bereits eine behelfsmäßige Lösung?</li><li>Ist der Schmerz dieses Jobs stark genug oder häufig genug?</li><li>Wenn ich es gut mache, wird der Nutzer merklich &quot;eine Zustandsverbesserung&quot; spüren?</li><li>Kann die erste Version nur um den wichtigsten Schritt dieses Jobs herum eine sehr kleine, aber nützliche Version sein?</li></ol><p>Wenn eine Richtung am Ende nur &quot;klingt interessant&quot; ist, aber keine klaren Auslöser, Alternativlösungen und Erfolgskriterien formuliert werden kann, ist sie wahrscheinlich eher eine vage Inspiration als eine ausgereifte Richtung.</p><h2 id="_8-interview-fragen-die-sie-direkt-verwenden-k-ouml-nnen" tabindex="-1">8. Interview-Fragen, die Sie direkt verwenden können <a class="header-anchor" href="#_8-interview-fragen-die-sie-direkt-verwenden-k-ouml-nnen" aria-label="Permalink to “8. Interview-Fragen, die Sie direkt verwenden k&amp;ouml;nnen”">​</a></h2><p>Viele beginnen eine Umfrage mit: &quot;Welche Funktionen möchten Sie?&quot; Diese Frage liefert leicht oberflächliche Antworten.</p><p>JTBD eignet sich besser für folgende Fragen:</p><ul><li>Wann hatten Sie das letzte Mal dieses Problem?</li><li>Was haben Sie damals getan und warum sind Sie hängengeblieben?</li><li>Wie haben Sie es schließlich gelöst?</li><li>Was war in diesem Prozess das Nervigste, Langsamste oder Beunruhigendste?</li><li>Wenn es ein Tool gäbe, das Ihnen hilft: Welches Ergebnis würde Sie wirklich überzeugen?</li><li>Welche Alternativmethoden haben Sie ausprobiert und warum waren sie nicht gut genug?</li></ul><p>Diese Frageweise hat einen Vorteil: Sie bringt das Gespräch zurück zu echten Erlebnissen, anstatt bei imaginären Präferenzen zu bleiben.</p><h2 id="_9-ai-nutzen-um-jtbd-analyse-durchzuf-uuml-hren" tabindex="-1">9. AI nutzen, um JTBD-Analyse durchzuführen <a class="header-anchor" href="#_9-ai-nutzen-um-jtbd-analyse-durchzuf-uuml-hren" aria-label="Permalink to “9. AI nutzen, um JTBD-Analyse durchzuf&amp;uuml;hren”">​</a></h2><p>JTBD wurde nicht von AI erfunden, aber AI eignet sich hervorragend, um JTBD zu ordnen und zu destillieren.</p><p>Wenn Sie beispielsweise 5 bis 10 Nutzer-Feedbacks gesammelt haben, können Sie diese dem Modell geben und es bitten, nach folgender Struktur zusammenzufassen:</p><div class="language-text"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>Bitte spiele die Rolle eines Produktforschungsassistenten.</span></span>
<span class="line"><span>Ich werde dir einige Nutzer-Originalzitate geben. Bitte gib zun&amp;auml;chst keine Funktionsvorschl&amp;auml;ge,</span></span>
<span class="line"><span>sondern ordne sie nach dem Jobs-to-Be-Done-Framework:</span></span>
<span class="line"><span></span></span>
<span class="line"><span>1. In welchem Szenario befindet sich der Nutzer</span></span>
<span class="line"><span>2. Was ist das ausl&amp;ouml;sende Ereignis f&amp;uuml;r seine Handlung</span></span>
<span class="line"><span>3. Welchen Fortschritt m&amp;ouml;chte er wirklich erreichen</span></span>
<span class="line"><span>4. Was ist die aktuelle Alternativl&amp;ouml;sung</span></span>
<span class="line"><span>5. Welches Erfolgskriterium ist ihm am wichtigsten</span></span>
<span class="line"><span>6. Welche Emotionsw&amp;ouml;rter tauchen in diesen Feedbacks wiederholt auf</span></span>
<span class="line"><span></span></span>
<span class="line"><span>Fasse abschlie&amp;szlig;end diese Inhalte in 3 priorisierte JTBD-Hypothesen zusammen.</span></span></code></pre></div><p>Wenn Sie bereits eine Idee haben, können Sie AI auch beim ersten Konvergierungsschritt unterstützen:</p><div class="language-text"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>Ich m&amp;ouml;chte [Ihre Produktidee] entwickeln.</span></span>
<span class="line"><span>Bitte gib mir nicht direkt eine Funktionsliste, sondern analysiere sie mit der Jobs-to-Be-Done-Methode:</span></span>
<span class="line"><span></span></span>
<span class="line"><span>1. Welche konkreten Szenarien k&amp;ouml;nnte dieses Produkt bedienen</span></span>
<span class="line"><span>2. Was ist der Kern-Job, den der Nutzer in jedem Szenario erreichen will</span></span>
<span class="line"><span>3. Welche bestehenden Alternativl&amp;ouml;sungen gibt es</span></span>
<span class="line"><span>4. Welcher Job eignet sich am besten als MVP-Startpunkt und warum</span></span>
<span class="line"><span>5. Formuliere den empfohlenen Job als klaren JTBD-Satz</span></span></code></pre></div><p>Der Vorteil: Sie werden nicht sofort von AI zu &quot;50 Funktionen brainstormen&quot; gedrängt, sondern klären zunächst die Richtung.</p><h2 id="_10-die-4-h-auml-ufigsten-fehler-von-einsteigern" tabindex="-1">10. Die 4 häufigsten Fehler von Einsteigern <a class="header-anchor" href="#_10-die-4-h-auml-ufigsten-fehler-von-einsteigern" aria-label="Permalink to “10. Die 4 h&amp;auml;ufigsten Fehler von Einsteigern”">​</a></h2><h3 id="_10-1-den-job-als-funktionsnamen-formulieren" tabindex="-1">10.1 Den Job als Funktionsnamen formulieren <a class="header-anchor" href="#_10-1-den-job-als-funktionsnamen-formulieren" aria-label="Permalink to “10.1 Den Job als Funktionsnamen formulieren”">​</a></h3><p>&quot;AI-Zusammenfassung&quot;, &quot;Intelligente Kategorisierung&quot;, &quot;Automatische Generierung&quot; sind keine Jobs, sondern nur mögliche Implementierungsweisen.</p><h3 id="_10-2-die-zielgruppe-zu-weit-formulieren" tabindex="-1">10.2 Die Zielgruppe zu weit formulieren <a class="header-anchor" href="#_10-2-die-zielgruppe-zu-weit-formulieren" aria-label="Permalink to “10.2 Die Zielgruppe zu weit formulieren”">​</a></h3><p>&quot;Alle Büroangestellten&quot;, &quot;Alle Studierenden&quot;, &quot;Alle Gründer&quot; sind meist zu allgemein. Je allgemeiner, desto schwerer erkennen Sie echte Szenarien.</p><h3 id="_10-3-nur-h-ouml-ren-was-nutzer-sagen-nicht-beobachten-was-nutzer-tun" tabindex="-1">10.3 Nur hören, was Nutzer sagen, nicht beobachten, was Nutzer tun <a class="header-anchor" href="#_10-3-nur-h-ouml-ren-was-nutzer-sagen-nicht-beobachten-was-nutzer-tun" aria-label="Permalink to “10.3 Nur h&amp;ouml;ren, was Nutzer sagen, nicht beobachten, was Nutzer tun”">​</a></h3><p>Nutzer beschreiben, was sie wollen, aber ihre wahren Prioritäten verstecken sich oft darin, wie sie aktuell improvisieren.</p><h3 id="_10-4-von-anfang-an-eine-komplette-plattform-bauen-wollen" tabindex="-1">10.4 Von Anfang an eine komplette Plattform bauen wollen <a class="header-anchor" href="#_10-4-von-anfang-an-eine-komplette-plattform-bauen-wollen" aria-label="Permalink to “10.4 Von Anfang an eine komplette Plattform bauen wollen”">​</a></h3><p>Die richtige Herangehensweise an JTBD ist meist nicht &quot;Ich baue eine All-in-One-Plattform&quot;, sondern zunächst den wichtigsten Schritt in einem Szenario ins Visier zu nehmen und ihn sehr handlich zu machen.</p><h2 id="_11-zusammenfassung" tabindex="-1">11. Zusammenfassung <a class="header-anchor" href="#_11-zusammenfassung" aria-label="Permalink to “11. Zusammenfassung”">​</a></h2><p>Der wertvollste Beitrag von Jobs to Be Done besteht nicht darin, Ihnen ein neues Schlagwort zu geben, sondern Ihnen zu helfen, die Perspektive zu wechseln: <strong>Nicht auf Produktfunktionen starren, sondern darauf, was Nutzer voranbringen möchten.</strong></p><p>Wenn Sie anfangen, sich wiederholt zu fragen:</p><ul><li>In welchem Szenario stellen Nutzer dieses Produkt ein</li><li>Wo genau hängen sie fest</li><li>Mit welcher Methode kämpfen sie sich aktuell durch</li><li>Wie ändert sich ihr Zustand, wenn das Problem gelöst ist</li></ul><p>werden Sie feststellen, dass viele ursprünglich vage Ideen plötzlich klar werden und viele ursprünglich beeindruckende Funktionen plötzlich weniger wichtig sind.</p><p>Bei der Produktentwicklung, besonders bei AI-Produkten, ist das Schlimmste, sich von Anfang an in der Präsentation von Fähigkeiten zu verlieren. JTBD hilft Ihnen, die Aufmerksamkeit auf das wirklich Wichtige zurückzulenken: <strong>Warum Nutzer Sie brauchen und welchen Fortschritt Sie ihnen ermöglichen.</strong></p><p><a id="jtbd-ai"></a></p><h2 id="_12-wie-sie-ai-nutzen-k-ouml-nnen-um-jtbd-zu-praktizieren" tabindex="-1"><a href="#top-jtbd">12. Wie Sie AI nutzen können, um JTBD zu praktizieren</a> <a class="header-anchor" href="#_12-wie-sie-ai-nutzen-k-ouml-nnen-um-jtbd-zu-praktizieren" aria-label="Permalink to “12. Wie Sie AI nutzen k&amp;ouml;nnen, um JTBD zu praktizieren”">​</a></h2><p>JTBD wurde nicht von AI erfunden, aber AI eignet sich hervorragend als Forschungsassistent, Ordnungsassistent und Gegenüber in dieser Methode. Der Schlüssel: <strong>AI beim Ordnen und Erweitern helfen lassen, nicht Nutzer für Sie erfinden lassen.</strong></p><p>Sie können es so einsetzen:</p><h3 id="_12-1-ai-helfen-lassen-vage-ideen-in-jtbd-hypothesen-umzuschreiben" tabindex="-1">12.1 AI helfen lassen, vage Ideen in JTBD-Hypothesen umzuschreiben <a class="header-anchor" href="#_12-1-ai-helfen-lassen-vage-ideen-in-jtbd-hypothesen-umzuschreiben" aria-label="Permalink to “12.1 AI helfen lassen, vage Ideen in JTBD-Hypothesen umzuschreiben”">​</a></h3><p>Wenn Sie nur eine vage Beschreibung im Kopf haben, wie &quot;Ich möchte ein Tool entwickeln, das Studierenden bei der Praktikumssuche hilft&quot;, können Sie zunächst AI bitten, es in mögliche Jobs aufzuteilen:</p><div class="language-text"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>Ich habe eine vage Produktidee: [Ihre Idee]</span></span>
<span class="line"><span>Bitte gib mir nicht direkt eine Funktionsliste, sondern analysiere sie mit der Jobs-to-Be-Done-Methode:</span></span>
<span class="line"><span>1. Welche konkreten Szenarien k&amp;ouml;nnten entsprechen</span></span>
<span class="line"><span>2. Welchen Fortschritt wollen Nutzer in jedem Szenario wirklich erreichen</span></span>
<span class="line"><span>3. Welche Alternativl&amp;ouml;sungen k&amp;ouml;nnten es geben</span></span>
<span class="line"><span>4. Welcher Job eignet sich am besten f&amp;uuml;r ein MVP</span></span>
<span class="line"><span>Formuliere abschlie&amp;szlig;end jeden Job als klaren JTBD-Satz.</span></span></code></pre></div><p>Sie können die Eingabe auch sehr anfängerhaft formulieren:</p><div class="language-text"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>Ich m&amp;ouml;chte etwas entwickeln, das Studierenden bei der Praktikumssuche hilft.</span></span>
<span class="line"><span>Ich kann noch nicht genau sagen, was es sein soll. Hilf mir herauszufinden, was Nutzer wirklich erreichen wollen.</span></span></code></pre></div><p>AI könnte folgende nützliche Ausgabe liefern:</p><div class="language-text"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>M&amp;ouml;gliche JTBD-Richtungen:</span></span>
<span class="line"><span></span></span>
<span class="line"><span>1. Wenn ich mich zum ersten Mal auf ein Praktikum bewerbe, m&amp;ouml;chte ich schnell wissen, welche Unterlagen ich zuerst vorbereiten sollte,</span></span>
<span class="line"><span>damit ich nicht wegen Informationschaos meine Bewerbung aufschiebe.</span></span>
<span class="line"><span></span></span>
<span class="line"><span>2. Wenn ich eine Praktikumsstelle sehe, m&amp;ouml;chte ich schnell beurteilen k&amp;ouml;nnen, ob es sich lohnt, mich zu bewerben,</span></span>
<span class="line"><span>damit ich nicht zu viel Zeit auf ungeeignete Stellen verschwende.</span></span>
<span class="line"><span></span></span>
<span class="line"><span>3. Wenn ich mit der Bewerbung beginne, m&amp;ouml;chte ich meinen bestehenden Lebenslauf in eine Version umschreiben, die besser zur Stelle passt,</span></span>
<span class="line"><span>damit ich schneller abschicken und die Erfolgsquote erh&amp;ouml;hen kann.</span></span></code></pre></div><p>Der Wert dieser Ausgabe liegt darin, Ihre ursprünglich sehr allgemeine Idee in mehrere richtungenähere Szenarien aufzuteilen.</p><h3 id="_12-2-ai-beim-ordnen-von-interview-originalzitaten-helfen-lassen" tabindex="-1">12.2 AI beim Ordnen von Interview-Originalzitaten helfen lassen <a class="header-anchor" href="#_12-2-ai-beim-ordnen-von-interview-originalzitaten-helfen-lassen" aria-label="Permalink to “12.2 AI beim Ordnen von Interview-Originalzitaten helfen lassen”">​</a></h3><p>Wenn Sie bereits mehrere Nutzer-Interviews durchgeführt haben, können Sie die Interviewaufzeichnungen an AI übergeben und sie bitten, wiederkehrende Szenarien, Auslöser, Alternativlösungen und Erfolgskriterien zu destillieren.</p><div class="language-text"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>Hier sind die Originalzitate von 5 Nutzern.</span></span>
<span class="line"><span>Bitte gib zun&amp;auml;chst keine L&amp;ouml;sungsvorschl&amp;auml;ge, sondern ordne sie nach dem JTBD-Framework:</span></span>
<span class="line"><span>1. In welchem Szenario befindet sich der Nutzer</span></span>
<span class="line"><span>2. Was ist das ausl&amp;ouml;sende Ereignis f&amp;uuml;r seine Handlung</span></span>
<span class="line"><span>3. Welchen Fortschritt m&amp;ouml;chte er wirklich erreichen</span></span>
<span class="line"><span>4. Was ist die aktuelle Alternativl&amp;ouml;sung</span></span>
<span class="line"><span>5. Welches Erfolgskriterium ist ihm am wichtigsten</span></span>
<span class="line"><span>6. Welche Informationen tauchen bei mehreren Nutzern wiederholt auf</span></span>
<span class="line"><span>Fasse abschlie&amp;szlig;end in 3 priorisierte JTBD-Hypothesen zusammen.</span></span></code></pre></div><p>Eine sehr einfache Eingabe könnte so aussehen:</p><div class="language-text"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>Ich habe 3 Personen gefragt, sie sagten ungef&amp;auml;hr Folgendes:</span></span>
<span class="line"><span></span></span>
<span class="line"><span>1. Jedes Mal, wenn ich mich auf ein Praktikum bewerbe, muss ich meinen Lebenslauf neu anpassen. Das ist extrem nervig.</span></span>
<span class="line"><span>2. Was ich eigentlich am meisten f&amp;uuml;rchte, ist, nicht zu wissen, ob ich es richtig mache.</span></span>
<span class="line"><span>3. Ich lasse derzeit &amp;auml;ltere Kommilitonen gegenlesen, aber es ist mir peinlich, st&amp;auml;ndig um Gef&amp;auml;lligkeiten zu bitten.</span></span>
<span class="line"><span></span></span>
<span class="line"><span>Hilf mir herauszufinden, was sie wirklich erreichen wollen.</span></span></code></pre></div><p>AI könnte ausgeben:</p><div class="language-text"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>Zusammenfassung:</span></span>
<span class="line"><span></span></span>
<span class="line"><span>- Gemeinsames Szenario: Vor der Praktikumsbewerbung muss der Lebenslauf bearbeitet werden</span></span>
<span class="line"><span>- Gemeinsame Schwierigkeit: Nicht wissen, wie man es &quot;gut genug&quot; macht</span></span>
<span class="line"><span>- Aktuelle Alternativl&amp;ouml;sung: &amp;Auml;ltere Kommilitonen bitten, selbstst&amp;auml;ndig wiederholt &amp;uuml;berarbeiten</span></span>
<span class="line"><span>- M&amp;ouml;glicher JTBD:</span></span>
<span class="line"><span>  Wenn ich mich auf ein Praktikum bewerbe, m&amp;ouml;chte ich schneller beurteilen k&amp;ouml;nnen, ob mein Lebenslauf abschickbereit ist,</span></span>
<span class="line"><span>  damit ich nicht st&amp;auml;ndig im &quot;Noch ein bisschen &amp;uuml;berarbeiten&quot; festh&amp;auml;nge und ihn nie verschicke.</span></span></code></pre></div><p>Diese Ausgabe ist sehr nützlich, denn sie hilft, aus verstreuten Originalzitaten etwas herauszudestillieren, das eher einem &quot;Bedarf&quot; entspricht.</p><h3 id="_12-3-ai-eine-leichte-webrecherche-durchf-uuml-hren-lassen" tabindex="-1">12.3 AI eine leichte Webrecherche durchführen lassen <a class="header-anchor" href="#_12-3-ai-eine-leichte-webrecherche-durchf-uuml-hren-lassen" aria-label="Permalink to “12.3 AI eine leichte Webrecherche durchf&amp;uuml;hren lassen”">​</a></h3><p>Bevor Sie mit umfangreichen Interviews beginnen, können Sie AI zunächst einen leichten Scan externer Informationen durchführen lassen:</p><ul><li>Wie wird in öffentlichen Foren oder Communitys über dieses Problem geklagt</li><li>Welche Probleme lösen bestehende Produkte hauptsächlich</li><li>Was ist die häufigste Alternativlösung der Nutzer</li><li>Was wird in Bewertungen am meisten gelobt und kritisiert</li></ul><p>Diese Recherche kann echte Nutzer-Interviews nicht ersetzen, eignet sich aber gut als Aufwärmübung in der Discover-Phase, um zunächst eine Problemlandkarte zu erstellen.</p><p>Ein einfacher Prompt könnte lauten:</p><div class="language-text"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>Bitte recherchiere f&amp;uuml;r mich:</span></span>
<span class="line"><span>&quot;Was sind die h&amp;auml;ufigsten Schmerzpunkte beim Umschreiben von Lebensl&amp;auml;ufen und Bewerben f&amp;uuml;r Praktika bei Studierenden?&quot;</span></span>
<span class="line"><span>Konzentriere dich auf das, was Leute in &amp;ouml;ffentlichen Foren, Erfahrungsberichten und Bewerbungs-Communitys selbst sagen.</span></span>
<span class="line"><span>Fasse es in 5 h&amp;auml;ufigsten Problemen zusammen.</span></span></code></pre></div><p>AI könnte ausgeben:</p><div class="language-text"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>H&amp;auml;ufigste Schmerzpunkte:</span></span>
<span class="line"><span></span></span>
<span class="line"><span>1. Nicht wissen, welche Erfahrungen im Lebenslauf stehen sollten</span></span>
<span class="line"><span>2. Nicht wissen, wie man f&amp;uuml;r verschiedene Stellen anpasst</span></span>
<span class="line"><span>3. Nach vielen &amp;Uuml;berarbeitungen immer noch unsicher, ob es gut genug ist</span></span>
<span class="line"><span>4. Keine zuverl&amp;auml;ssige Person zum Gegenlesen finden</span></span>
<span class="line"><span>5. Komplexer Bewerbungsprozess, der zum Aufschieben verleitet</span></span></code></pre></div><p>Diese Art von Ausgabe kann nicht als endgültige Schlussfolgerung dienen, hilft aber zu entscheiden, welche Art von Problem priorisiert interviewt werden sollte.</p><h3 id="_12-4-ai-als-gegenspieler-fungieren-lassen" tabindex="-1">12.4 AI als &quot;Gegenspieler&quot; fungieren lassen <a class="header-anchor" href="#_12-4-ai-als-gegenspieler-fungieren-lassen" aria-label="Permalink to “12.4 AI als &quot;Gegenspieler&quot; fungieren lassen”">​</a></h3><p>Oft sind wir zu sehr mit unseren eigenen Ideen verbunden. Sie können AI gezielt als kritischen Gegenüber einsetzen, der Sie zwingt, das Problem klarer zu formulieren:</p><div class="language-text"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>Bitte spiele die Rolle eines sehr strengen Produktforschungsberaters.</span></span>
<span class="line"><span>Hier ist meine JTBD-Hypothese: [Ihre Hypothese]</span></span>
<span class="line"><span>Kritisiere sie aus folgenden Perspektiven:</span></span>
<span class="line"><span>1. Ist dieses Szenario zu weit gefasst</span></span>
<span class="line"><span>2. Wurde dieser Job als Funktion statt als echter Fortschritt formuliert</span></span>
<span class="line"><span>3. Ist die Alternativl&amp;ouml;sung zu schwach</span></span>
<span class="line"><span>4. Ist das Erfolgskriterium unklar</span></span>
<span class="line"><span>5. Was ist das gr&amp;ouml;&amp;szlig;te Risiko, das bei dieser Hypothese validiert werden muss</span></span></code></pre></div><p>Der Vorteil: Sie erkennen schneller, ob Sie sich auf den Bedarf oder nur auf Ihre bevorzugte Lösung konzentrieren.</p><h2 id="assignments" tabindex="-1">Assignments <a class="header-anchor" href="#assignments" aria-label="Permalink to “Assignments”">​</a></h2><p>Bitte bearbeiten Sie die folgenden Aufgaben basierend auf dem obigen Inhalt:</p><ol><li>Wählen Sie eine Produktidee, an die Sie kürzlich gedacht haben, und formulieren Sie sie mit einer JTBD-Formel klar</li><li>Ergänzen Sie diese Idee mit den 5 Elementen: Szenario, Auslöser, Fortschritt, Alternativlösung, Erfolgskriterium</li><li>Finden Sie 3 potenzielle Nutzer und fragen Sie mindestens einmal: &quot;Wann hatten Sie das letzte Mal dieses Problem?&quot;</li><li>Übergeben Sie die Interview-Originalzitate an AI und fassen Sie sie in 3 priorisierte JTBD-Hypothesen zusammen</li></ol><h2 id="weiterf-uuml-hrende-literatur" tabindex="-1">Weiterführende Literatur <a class="header-anchor" href="#weiterf-uuml-hrende-literatur" aria-label="Permalink to “Weiterf&amp;uuml;hrende Literatur”">​</a></h2><ul><li><a href="https://www.christenseninstitute.org/theory/jobs-to-be-done/" target="_blank" rel="noreferrer">Christensen Institute: Jobs to Be Done</a></li><li><a href="https://online.hbs.edu/blog/post/jobs-to-be-done" target="_blank" rel="noreferrer">Harvard Business School Online: What Is Jobs to Be Done?</a></li><li><a href="https://www.intercom.com/blog/jobs-to-be-done-framework/" target="_blank" rel="noreferrer">Intercom: Jobs-to-be-Done: A framework for customer needs</a></li><li><a href="https://www.mural.co/blog/jobs-to-be-done-framework" target="_blank" rel="noreferrer">Mural: Jobs to Be Done framework guide</a></li></ul>`,148))])}}});export{g as __pageData,b as default};
